package greeter

import "strings"

// Slug 把 s 转成小写的连字符形式：去掉首尾空白，连续空白折成一个 "-"。
func Slug(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		in, want string
	}{
		{"Hello World", "hello-world"},
		{"  Hello World  ", "hello-world"},
		{"a   b", "a-b"},
	}
	for _, c := range cases {
		if got := Slug(c.in); got != c.want {
			t.Errorf("Slug(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

package greeter

import "strings"

// JoinSlug 对每个 part 做 Slug，跳过空串与纯空白，再用 "/" 连接。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, p := range parts {
		if s := Slug(p); s != "" {
			slugs = append(slugs, s)
		}
	}
	return strings.Join(slugs, "/")
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	if got := JoinSlug("Hello World", "Big Day"); got != "hello-world/big-day" {
		t.Errorf("JoinSlug(Hello World, Big Day) = %q", got)
	}
	if got := JoinSlug("a", "", "b"); got != "a/b" {
		t.Errorf("JoinSlug(a, , b) = %q", got)
	}
	if got := JoinSlug("a", "   ", "b"); got != "a/b" {
		t.Errorf("JoinSlug(a, blank, b) = %q", got)
	}
}
